import { MeshBasicNodeMaterial, PlaneGeometry, Mesh, Group, Vector3 } from 'three/webgpu';
import { uv, vec2, texture, mix, sin, cos, length, time, vec4, color, float, Fn } from 'three/tsl';
import gsap from 'gsap';

export default function createNode(config, ctx) {
  const group = new Group();
  group.name = config.id || 'features-card-1-label';
  group.userData.handlers = {};

  // --- Plane geometry (aspect ratio from atlas region: 512x320 => 1.6:1) ---
  const aspect = 512 / 320;
  const width = 2.0;
  const height = width / aspect;
  const geometry = new PlaneGeometry(width, height);

  // --- Image texture ---
  const imageUrl = config.assets?.imageUrl;
  let textureMap = null;
  if (imageUrl) {
    textureMap = ctx.textureLoader.load(imageUrl);
    textureMap.needsUpdate = true;
  }

  // --- Procedural gradient + grain shader using TSL ---
  const gradientGrainMaterial = new MeshBasicNodeMaterial();

  const uvNode = uv();
  // Engineered gradient: slight vertical gradient from dark surface to ink
  const gradient = mix(
    color(config.colors?.surface || '#0b0b10').toNode,
    color(config.colors?.ink || '#16161d').toNode,
    uvNode.y
  );

  // Subtle grain noise (procedural)
  const grain = Fn(() => {
    const n = length(
      vec2(
        sin(uvNode.x * 200.0 + uvNode.y * 50.0 + time * 0.2),
        cos(uvNode.y * 150.0 + uvNode.x * 30.0 + time * 0.15)
      )
    );
    return n.mul(0.15).add(0.85); // subtle variation
  })();

  // Combine with image texture if available
  let finalColor;
  if (textureMap) {
    const imgColor = texture(textureMap, uvNode);
    // Blend: multiply gradient and grain over image (semi-transparent overlay)
    const overlay = gradient.mul(grain);
    finalColor = mix(imgColor, overlay, 0.3);
  } else {
    finalColor = gradient.mul(grain);
  }

  gradientGrainMaterial.colorNode = finalColor;
  gradientGrainMaterial.side = 2; // DoubleSide

  const planeMesh = new Mesh(geometry, gradientGrainMaterial);
  planeMesh.position.set(0, 0, 0);
  group.add(planeMesh);

  // --- Text: "Features 1" as headline ---
  const textStr = config.textContent?.headline || 'Features 1';
  const textHeight = 0.34; // from design tokens: headline = 0.34 scene units
  const textMesh = ctx.fontAtlas.createText?.(textStr, {
    font: 'Lora',
    fontWeight: 400,
    fontSize: textHeight,
    color: config.colors?.paper || '#e8ecf2',
  });

  // If fontAtlas returns a Mesh or Object3D, add and position
  if (textMesh) {
    textMesh.position.set(0, -0.2, 0.001); // slightly above plane surface
    group.add(textMesh);
  } else if (ctx.fontAtlas.getTextGeometry) {
    // Fallback: using geometry approach
    const textGeo = ctx.fontAtlas.getTextGeometry(textStr, {
      font: 'Lora',
      fontWeight: 400,
      fontSize: textHeight,
    });
    const textMat = new MeshBasicNodeMaterial({
      colorNode: color(config.colors?.paper || '#e8ecf2').toNode,
      transparent: true,
    });
    const textMesh2 = new Mesh(textGeo, textMat);
    textMesh2.position.set(-textGeo.boundingBox.max.x / 2, -0.2, 0.001);
    group.add(textMesh2);
  }

  // --- Scene placement ---
  if (config.scenePosition) {
    group.position.copy(new Vector3(config.scenePosition[0], config.scenePosition[1], config.scenePosition[2]));
  }
  if (config.sceneRotation) {
    group.rotation.set(config.sceneRotation[0], config.sceneRotation[1], config.sceneRotation[2]);
  }
  if (config.sceneScale) {
    group.scale.set(config.sceneScale[0], config.sceneScale[1], config.sceneScale[2]);
  }

  // --- Cleanup ---
  group.userData.cleanup = () => {
    geometry.dispose();
    gradientGrainMaterial.dispose();
    if (textureMap) textureMap.dispose();
    if (textMesh) {
      if (textMesh.geometry) textMesh.geometry.dispose();
      if (textMesh.material) textMesh.material.dispose();
    }
    // Kill any GSAP tweens on this node (none in this case)
    gsap.killTweensOf(group);
  };

  return group;
}
